from test_target_priority import test, priority

test('Disabled fallback preserves own other blessing',priority+"BuffTap.db.targetBlessingFallback=false; aura('target',19742,'Blessing of Wisdom'); auras.target[1].sourceUnit='player'; refresh(); assert(not BuffTap.action.quickTarget)")
test('Disabled fallback still offers first missing choice',priority+"BuffTap.db.targetBlessingFallback=false; refresh(); assert(BuffTap.action.key=='bok' and BuffTap.action.quickTarget)")
test('Unknown ownership reports safety reason',priority+"aura('target',20217,'Blessing of Kings'); BuffTap:InvalidateAura(); BuffTap:Refresh(true); assert(BuffTap.targetDataPending); assert(table.concat(BuffTap.diagnostics,';'):find('caster unknown',1,true))")
test('Unreadable class reports reason',priority+"local old=UnitClass; UnitClass=function(u) if u=='target' then return nil end return old(u) end; BuffTap:Refresh(true); assert(BuffTap.targetDataPending and table.concat(BuffTap.diagnostics,';'):find('target class unavailable',1,true))")
test('Late target metadata recovers without reselection',priority+"local old=UnitClass; UnitClass=function(u) if u=='target' then return nil end return old(u) end; BuffTap.events.scripts.OnEvent(nil,'PLAYER_TARGET_CHANGED'); advance(.7); assert(BuffTap.targetDataPending); UnitClass=old; advance(1.4); assert(BuffTap.action.quickTarget and BuffTap.action.key=='bok' and not BuffTap.targetDataPending)")
test('Extended retries are bounded and stop after recovery',priority+"BuffTap:ResetStats(); BuffTap.events.scripts.OnEvent(nil,'PLAYER_TARGET_CHANGED'); advance(6); assert(BuffTap.stats.targetRetries==2); local n=BuffTap.stats.targetRetries; advance(20); assert(BuffTap.stats.targetRetries==n)")
test('Unknown ownership extended retries remain bounded',priority+"aura('target',20217,'Blessing of Kings'); BuffTap:ResetStats(); BuffTap.events.scripts.OnEvent(nil,'PLAYER_TARGET_CHANGED'); advance(6); assert(BuffTap.stats.targetRetries==4 and BuffTap.targetDataPending); advance(20); assert(BuffTap.stats.targetRetries==4)")
test('Dismissal is explicitly diagnosed',priority+"BuffTap.db.helperDismiss=true; BuffTap:DismissHelper(BuffTap.action,'test'); advance(.1); BuffTap:Refresh(true); assert(table.concat(BuffTap.diagnostics,';'):find('Restore reminders',1,true))")

test('Late ownership recovers safely to next blessing',priority+"aura('target',20217,'Blessing of Kings'); BuffTap.events.scripts.OnEvent(nil,'PLAYER_TARGET_CHANGED'); advance(.7); auras.target[1].sourceUnit='other'; advance(1.4); assert(BuffTap.action.quickTarget and BuffTap.action.key=='bow')")
test('Changing target invalidates delayed retries',priority+"aura('target',20217,'Blessing of Kings'); BuffTap.events.scripts.OnEvent(nil,'PLAYER_TARGET_CHANGED'); advance(.7); auras.target={}; BuffTap.events.scripts.OnEvent(nil,'PLAYER_TARGET_CHANGED'); advance(6); assert(BuffTap.action.key=='bok' and BuffTap.action.quickTarget and not BuffTap.targetDataPending)")
test('Unreadable aura reports scan failure',priority+"C_UnitAuras.GetAuraDataByIndex=function() error('unavailable') end; BuffTap:InvalidateAura(); BuffTap:Refresh(true); assert(BuffTap.targetDataPending and table.concat(BuffTap.diagnostics,';'):find('aura scan unavailable',1,true))")
